import React, { useEffect, useState, useRef } from "react";
import { 
  Card, 
  Typography, 
  Button, 
  Space, 
  Tabs, 
  Statistic, 
  Row, 
  Col, 
  Select,
  Slider,
  Switch,
  Input,
  message,
  Spin,
  Alert
} from "antd";
import {
  ShareAltOutlined as NetworkIcon,
  EyeOutlined as EyeIcon,
  DownloadOutlined as DownloadIcon,
  SearchOutlined as SearchIcon,
  LineChartOutlined as TrendingUpIcon,
  ApiOutlined as BrainIcon,
  ThunderboltOutlined as ZapIcon,
  FilterOutlined as FilterIcon
} from "@ant-design/icons";
import EnhancedGraphCanvas, { EnhancedGraphCanvasHandle, GraphData } from "../components/EnhancedGraphCanvas";
import { getTelegramUser, apiRequest } from "../api";

const { Title, Text } = Typography;
const { Search } = Input;

interface GraphMetrics {
  total_nodes: number;
  total_edges: number;
  avg_energy: number;
  max_energy: number;
  clusters_count: number;
  connectivity: number;
}

interface VisualizationSettings {
  center_id?: string;
  depth: number;
  min_energy: number;
  max_nodes: number;
  include_archived: boolean;
  connection_threshold: number;
}

export default function SoulVisualization() {
  const [loading, setLoading] = useState(false);
  const [graphData, setGraphData] = useState<GraphData | null>(null);
  const [metrics, setMetrics] = useState<GraphMetrics | null>(null);
  const [selectedNode, setSelectedNode] = useState<any>(null);
  const [neighbors, setNeighbors] = useState<any[]>([]);
  const [neighborsLoading, setNeighborsLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [settings, setSettings] = useState<VisualizationSettings>({
    depth: 2,
    min_energy: 0.1,
    max_nodes: 100,
    include_archived: false,
    connection_threshold: 0.2
  });
  
  const graphRef = useRef<EnhancedGraphCanvasHandle>(null);


  const loadGraphData = async (centerNodeId?: string) => {
    try {
      setLoading(true);
      
      const params = new URLSearchParams({
        depth: settings.depth.toString(),
        min_energy: settings.min_energy.toString(),
        max_nodes: settings.max_nodes.toString(),
        include_archived: settings.include_archived.toString(),
        connection_threshold: settings.connection_threshold.toString()
      });
      
      if (centerNodeId) {
        params.append('center_id', centerNodeId);
      }
      
      let data = await apiRequest(`/admin/soul/graph/visual_subgraph?${params}`, "GET");
      if ((!data.nodes || data.nodes.length === 0) && (!data.edges || data.edges.length === 0)) {
        // Fallback #1: обзорный граф
        data = await apiRequest(`/admin/soul/graph/visual_overview?limit_nodes=${settings.max_nodes}&min_strength=${settings.connection_threshold}`, "GET");
      }
      if ((!data.nodes || data.nodes.length === 0) && (!data.edges || data.edges.length === 0)) {
        // Fallback #2: hubs + strong_edges
        const hubsResp = await apiRequest(`/admin/soul/graph/hubs?min_strength=0&limit=${Math.min(200, Math.max(20, settings.max_nodes))}`, "GET");
        const edgesResp = await apiRequest(`/admin/soul/graph/strong_edges?min_strength=0&limit=${Math.min(2000, settings.max_nodes * 10)}`, "GET");
        const hubNodes = (hubsResp.items || []).map((h: any) => ({
          id: String(h.quant_id),
          energy_weight: Number(h.energy_weight || 0),
          thought_form: String(h.thought_form || ""),
        }));
        const allowed = new Set(hubNodes.map((n: any) => n.id));
        const allEdges = (edgesResp.items || []).filter((e: any) => allowed.has(String(e.source)) && allowed.has(String(e.target)));
        data = { nodes: hubNodes, edges: allEdges };
      }
        
        // Преобразуем данные в формат для графа
        const graphData: GraphData = {
          nodes: data.nodes || [],
          edges: data.edges || []
        };
        
        setGraphData(graphData);
        
        // Вычисляем метрики
        const nodeCount = graphData.nodes.length;
        const metrics: GraphMetrics = {
          total_nodes: nodeCount,
          total_edges: graphData.edges.length,
          avg_energy: nodeCount > 0 ? (graphData.nodes.reduce((sum, node) => sum + (node.energy_weight || 0), 0) / nodeCount) : 0,
          max_energy: nodeCount > 0 ? Math.max(...graphData.nodes.map(node => node.energy_weight || 0)) : 0,
          clusters_count: estimateClusters(graphData),
          connectivity: graphData.edges.length / Math.max(1, nodeCount)
        };
        
        setMetrics(metrics);
        
        message.success(`Загружен граф: ${metrics.total_nodes} узлов, ${metrics.total_edges} связей`);
      
    } catch (error) {
      console.error("Ошибка загрузки графа:", error);
      message.error("Ошибка загрузки данных графа");
    } finally {
      setLoading(false);
    }
  };

  const loadNeighbors = async (nodeId: string) => {
    try {
      setNeighborsLoading(true);
      const resp = await apiRequest(`/admin/soul/graph/top_neighbors?quant_id=${encodeURIComponent(nodeId)}&limit=50`, "GET");
      setNeighbors(Array.isArray(resp.items) ? resp.items : []);
    } catch (e) {
      setNeighbors([]);
    } finally {
      setNeighborsLoading(false);
    }
  };

  const searchNodes = async (query: string) => {
    if (!query.trim()) {
      await loadGraphData();
      return;
    }
    
    try {
      setLoading(true);
      
      const response = await fetch(`/api/admin/soul/search/nodes?q=${encodeURIComponent(query)}&limit=50`, {
        headers: buildAuthHeaders()
      });
      
      if (response.ok) {
        const data = await response.json();
        const foundNodes = data.nodes || [];
        
        if (foundNodes.length > 0) {
          // Загружаем граф вокруг найденных узлов
          const centerNodeId = foundNodes[0].id;
          await loadGraphData(centerNodeId);
          
          // Фокусируемся на найденном узле
          if (graphRef.current) {
            graphRef.current.focusNode(centerNodeId);
          }
          
          message.success(`Найдено узлов: ${foundNodes.length}`);
        } else {
          message.info("Узлы не найдены");
        }
      }
      
    } catch (error) {
      console.error("Ошибка поиска:", error);
      message.error("Ошибка поиска узлов");
    } finally {
      setLoading(false);
    }
  };

  const estimateClusters = (data: GraphData): number => {
    // Простая оценка количества кластеров на основе связности
    const nodeIds = new Set(data.nodes.map(n => n.id));
    const visited = new Set<string>();
    let clusters = 0;
    
    for (const node of data.nodes) {
      if (visited.has(node.id)) continue;
      
      // BFS для поиска связанных компонентов
      const queue = [node.id];
      visited.add(node.id);
      
      while (queue.length > 0) {
        const currentId = queue.shift()!;
        
        // Находим все связанные узлы
        for (const edge of data.edges) {
          let connectedId: string | null = null;
          
          if (edge.source === currentId && !visited.has(edge.target)) {
            connectedId = edge.target;
          } else if (edge.target === currentId && !visited.has(edge.source)) {
            connectedId = edge.source;
          }
          
          if (connectedId && nodeIds.has(connectedId)) {
            visited.add(connectedId);
            queue.push(connectedId);
          }
        }
      }
      
      clusters++;
    }
    
    return clusters;
  };

  const handleNodeClick = (node: any) => {
    setSelectedNode(node);
    if (node?.id) loadNeighbors(node.id);
  };

  const unlinkEdge = async (fromId: string, toId: string) => {
    try {
      const reason = window.prompt('Причина разрыва связи:', '') || '';
      const body = { from_quant_id: fromId, to_quant_id: toId, bidirectional: true, reason };
      await apiRequest('/admin/soul/graph/unlink_edge', 'POST', body);
      message.success('Связь разорвана');
      // Обновим локальные данные графа
      setGraphData(prev => prev ? ({
        nodes: prev.nodes,
        edges: prev.edges.filter(e => !( (e.source === fromId && e.target === toId) || (e.source === toId && e.target === fromId) ))
      }) : prev);
      if (selectedNode?.id) loadNeighbors(selectedNode.id);
    } catch (e: any) {
      message.error('Не удалось разорвать связь');
    }
  };

  const restoreEdge = async (fromId: string) => {
    try {
      const toId = window.prompt('ID второго узла (to_quant_id):', '') || '';
      if (!toId) return;
      const type = window.prompt('Тип связи (semantic|causal|episodic|goal_link):', 'semantic') || 'semantic';
      const strengthStr = window.prompt('Сила связи (0..1):', '0.5') || '0.5';
      const overlapStr = window.prompt('Пересечение ключевых слов (0..1):', '0.0') || '0.0';
      const reason = window.prompt('Причина восстановления:', '') || '';
      const body = {
        from_quant_id: fromId,
        to_quant_id: toId,
        connection_type: type,
        connection_strength: Math.max(0, Math.min(1, parseFloat(strengthStr))),
        keyword_overlap: Math.max(0, Math.min(1, parseFloat(overlapStr))),
        bidirectional: false,
        reason
      };
      await apiRequest('/admin/soul/graph/restore_edge', 'POST', body);
      message.success('Связь восстановлена');
      // Локально добавим ребро
      setGraphData(prev => prev ? ({
        nodes: prev.nodes,
        edges: [...prev.edges, { source: fromId, target: toId, strength: body.connection_strength, connection_type: type, keyword_overlap: body.keyword_overlap }]
      }) : prev);
      if (selectedNode?.id) loadNeighbors(selectedNode.id);
    } catch (e: any) {
      message.error('Не удалось восстановить связь');
    }
  };

  const exportGraph = (format: 'png' | 'json') => {
    if (format === 'png' && graphRef.current) {
      const dataUrl = graphRef.current.exportPNG();
      if (dataUrl) {
        const link = document.createElement('a');
        link.download = `soul-graph-${Date.now()}.png`;
        link.href = dataUrl;
        link.click();
        message.success('Граф экспортирован как PNG');
      }
    } else if (format === 'json' && graphData) {
      const dataStr = JSON.stringify(graphData, null, 2);
      const dataBlob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(dataBlob);
      
      const link = document.createElement('a');
      link.download = `soul-graph-data-${Date.now()}.json`;
      link.href = url;
      link.click();
      
      URL.revokeObjectURL(url);
      message.success('Данные графа экспортированы как JSON');
    }
  };

  useEffect(() => {
    loadGraphData();
  }, []);

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <div style={{ marginBottom: 'var(--sp-spacing-sm)' }}>
        <Title level={2}>
          <NetworkIcon style={{ marginRight: 8, verticalAlign: 'middle' }} />
          Визуализация Soul
        </Title>
        <Text type="secondary">Интерактивная визуализация графа Квантов сознания Soul</Text>
      </div>

      <Row gutter={[16, 16]}>
        {/* Панель управления */}
        <Col xs={24} lg={6}>
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            {/* Поиск */}
            <Card title="Поиск" size="small">
              <Search
                placeholder="Поиск по содержимому Квантов..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onSearch={searchNodes}
                loading={loading}
                enterButton={<SearchIcon size={16} />}
              />
            </Card>

            {/* Настройки визуализации */}
            <Card title="Настройки" size="small">
              <Space direction="vertical" style={{ width: '100%' }} size="small">
                <div>
                  <Text>Глубина связей: {settings.depth}</Text>
                  <Slider
                    min={1}
                    max={5}
                    value={settings.depth}
                    onChange={(value) => setSettings(prev => ({ ...prev, depth: value }))}
                  />
                </div>
                
                <div>
                  <Text>Мин. энергия: {settings.min_energy}</Text>
                  <Slider
                    min={0}
                    max={1}
                    step={0.01}
                    value={settings.min_energy}
                    onChange={(value) => setSettings(prev => ({ ...prev, min_energy: value }))}
                  />
                </div>
                
                <div>
                  <Text>Макс. узлов: {settings.max_nodes}</Text>
                  <Slider
                    min={10}
                    max={500}
                    value={settings.max_nodes}
                    onChange={(value) => setSettings(prev => ({ ...prev, max_nodes: value }))}
                  />
                </div>
                
                <div>
                  <Text>Порог связей: {settings.connection_threshold}</Text>
                  <Slider
                    min={0}
                    max={1}
                    step={0.01}
                    value={settings.connection_threshold}
                    onChange={(value) => setSettings(prev => ({ ...prev, connection_threshold: value }))}
                  />
                </div>
                
                <div>
                  <Switch
                    checked={settings.include_archived}
                    onChange={(checked) => setSettings(prev => ({ ...prev, include_archived: checked }))}
                  />
                  <Text style={{ marginLeft: 8 }}>Включить архивные</Text>
                </div>
                
                <Button 
                  type="primary" 
                  block 
                  onClick={() => loadGraphData()}
                  loading={loading}
                >
                  Применить настройки
                </Button>
              </Space>
            </Card>

            {/* Метрики */}
            {metrics && (
              <Card title="Метрики графа" size="small">
                <Row gutter={[8, 8]}>
                  <Col span={12}>
                    <Statistic
                      title="Узлы"
                      value={metrics.total_nodes}
                      prefix={<BrainIcon size={16} />}
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic
                      title="Связи"
                      value={metrics.total_edges}
                      prefix={<NetworkIcon size={16} />}
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic
                      title="Ср. энергия"
                      value={metrics.avg_energy}
                      precision={3}
                      prefix={<ZapIcon size={16} />}
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic
                      title="Кластеры"
                      value={metrics.clusters_count}
                      prefix={<FilterIcon size={16} />}
                    />
                  </Col>
                </Row>
              </Card>
            )}

            {/* Экспорт */}
            <Card title="Экспорт" size="small">
              <Space direction="vertical" style={{ width: '100%' }}>
                <Button 
                  block 
                  icon={<DownloadIcon size={16} />}
                  onClick={() => exportGraph('png')}
                >
                  Экспорт PNG
                </Button>
                <Button 
                  block 
                  icon={<DownloadIcon size={16} />}
                  onClick={() => exportGraph('json')}
                >
                  Экспорт JSON
                </Button>
              </Space>
            </Card>

            {/* Действия со связями для выбранного узла */}
            {selectedNode && (
              <Card title="Связи узла" size="small">
                <Space direction="vertical" style={{ width: '100%' }}>
                  <Button
                    type="dashed"
                    onClick={() => restoreEdge(selectedNode.id)}
                    disabled={!selectedNode?.id}
                  >
                    Создать/восстановить связь…
                  </Button>
                  <div style={{ maxHeight: 240, overflow: 'auto', border: '1px solid var(--sp-border-color, var(--border-color))', padding: 8, borderRadius: 6 }}>
                    {neighborsLoading ? (
                      <Spin />
                    ) : neighbors.length === 0 ? (
                      <Text type="secondary">Соседи не найдены</Text>
                    ) : (
                      <Space direction="vertical" style={{ width: '100%' }} size={8}>
                        {neighbors.map((n: any) => (
                          <div key={n.neighbor_id} style={{ display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between' }}>
                            <div>
                              <div><Text strong>ID:</Text> {n.neighbor_id}</div>
                              <div style={{ fontSize: 12 }}>
                                <Text type="secondary">strength: {(n.strength || 0).toFixed(3)} · overlap: {(n.keyword_overlap || 0).toFixed(3)}</Text>
                              </div>
                            </div>
                            <Button size="small" danger onClick={() => unlinkEdge(selectedNode.id, n.neighbor_id)}>Разорвать</Button>
                          </div>
                        ))}
                      </Space>
                    )}
                  </div>
                </Space>
              </Card>
            )}
          </Space>
        </Col>

        {/* Основная область визуализации */}
        <Col xs={24} lg={18}>
          <Card>
            <Spin spinning={loading}>
              {graphData ? (
                <EnhancedGraphCanvas
                  ref={graphRef}
                  data={graphData}
                  width={800}
                  height={600}
                  onNodeClick={handleNodeClick}
                  showHeatmap={false}
                  showClusters={true}
                  showTrends={true}
                  enableFiltering={true}
                />
              ) : (
                <div style={{ height: 600, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--sp-surface-muted, #fafafa)', border: '2px dashed var(--sp-border-color, #d9d9d9)', borderRadius: 8 }}>
                  <Space direction="vertical" align="center">
                    <NetworkIcon size={48} style={{ color: 'var(--sp-icon-muted, #bfbfbf)' }} />
                    <Text type="secondary">Граф не загружен</Text>
                    <Button type="primary" onClick={() => loadGraphData()}>
                      Загрузить граф
                    </Button>
                  </Space>
                </div>
              )}
            </Spin>
          </Card>
        </Col>
      </Row>

      {/* Информация о выбранном узле */}
      {selectedNode && (
        <Card 
          title="Детали узла" 
          style={{ marginTop: 'var(--sp-spacing-sm)' }}
          extra={
            <Button 
              size="small" 
              onClick={() => { setSelectedNode(null); setNeighbors([]); }}
            >
              Закрыть
            </Button>
          }
        >
          <Tabs defaultActiveKey="general">
            <Tabs.TabPane tab="Общее" key="general">
              <Row gutter={[16, 16]}>
                <Col span={12}>
                  <Statistic
                    title="ID"
                    value={selectedNode.id}
                    valueStyle={{ fontSize: 14 }}
                  />
                </Col>
                <Col span={12}>
                  <Statistic
                    title="Энергия"
                    value={selectedNode.energy_weight || 0}
                    precision={4}
                    prefix={<ZapIcon size={16} />}
                  />
                </Col>
                {selectedNode.delta_energy && (
                  <Col span={12}>
                    <Statistic
                      title="Изменение энергии"
                      value={selectedNode.delta_energy}
                      precision={4}
                      valueStyle={{ 
                        color: selectedNode.delta_energy > 0 ? '#52c41a' : '#f5222d' 
                      }}
                      prefix={
                        selectedNode.delta_energy > 0 ? 
                        <TrendingUpIcon size={16} /> : 
                        <TrendingUpIcon size={16} style={{ transform: 'rotate(180deg)' }} />
                      }
                    />
                  </Col>
                )}
                <Col span={12}>
                  <Statistic
                    title="Состояние"
                    value={selectedNode.state || 'unknown'}
                  />
                </Col>
              </Row>
            </Tabs.TabPane>
            
            <Tabs.TabPane tab="Содержание" key="content">
              {selectedNode.thought_form && (
                <div style={{ marginBottom: 16 }}>
                  <Text strong>Форма мысли:</Text>
                  <div style={{ marginTop: 8, padding: 12, background: 'var(--sp-surface-muted, #f5f5f5)', borderRadius: 6, whiteSpace: 'pre-wrap' }}>
                    {selectedNode.thought_form}
                  </div>
                </div>
              )}
              
              {selectedNode.tags && selectedNode.tags.length > 0 && (
                <div style={{ marginBottom: 16 }}>
                  <Text strong>Теги:</Text>
                  <div style={{ marginTop: 8 }}>
                    <Space wrap>
                      {selectedNode.tags.map((tag: string, index: number) => (
                        <Button key={index} size="small" type="default">
                          {tag}
                        </Button>
                      ))}
                    </Space>
                  </div>
                </div>
              )}
            </Tabs.TabPane>
            
            <Tabs.TabPane tab="Эмоции" key="emotions">
              {selectedNode.composite_emotion ? (
                <Row gutter={[16, 16]}>
                  <Col span={8}>
                    <Statistic
                      title="Эмоция"
                      value={selectedNode.composite_emotion.label || 'Неопределена'}
                    />
                  </Col>
                  <Col span={8}>
                    <Statistic
                      title="Валентность"
                      value={selectedNode.composite_emotion.valence || 0}
                      precision={3}
                      valueStyle={{ 
                        color: (selectedNode.composite_emotion.valence || 0) > 0 ? '#52c41a' : '#f5222d' 
                      }}
                    />
                  </Col>
                  <Col span={8}>
                    <Statistic
                      title="Интенсивность"
                      value={selectedNode.composite_emotion.intensity || 0}
                      precision={3}
                    />
                  </Col>
                </Row>
              ) : (
                <Alert message="Эмоциональные данные отсутствуют" type="info" />
              )}
            </Tabs.TabPane>
          </Tabs>
        </Card>
      )}
    </div>
  );
}
