import React, { useEffect, useRef, useState, forwardRef, useImperativeHandle, useCallback } from "react";
import { Button, Space, Slider, Switch, Select, Tooltip, Card } from "antd";
import {
  ZoomInOutlined as ZoomInIcon,
  ZoomOutOutlined as ZoomOutIcon,
  DownloadOutlined as DownloadIcon,
  ReloadOutlined as RotateCcwIcon,
  EyeOutlined as EyeIcon,
  FilterOutlined as FilterIcon,
  LineChartOutlined as TrendingUpIcon
} from "@ant-design/icons";

type Node = { 
  id: string; 
  x?: number; 
  y?: number; 
  energy_weight?: number; 
  delta_energy?: number; 
  tags?: string[]; 
  thought_form?: string;
  state?: string;
  created_at?: string;
  composite_emotion?: {
    label?: string;
    valence?: number;
    intensity?: number;
  };
};

type Edge = { 
  source: string; 
  target: string; 
  strength?: number;
  connection_type?: string;
  keyword_overlap?: number;
};

export type GraphData = { nodes: Node[]; edges: Edge[] };

type Props = {
  data: GraphData | null;
  width?: number;
  height?: number;
  onNodeClick?: (node: Node) => void;
  onEdgeClick?: (edge: Edge) => void;
  showHeatmap?: boolean;
  showClusters?: boolean;
  showTrends?: boolean;
  enableFiltering?: boolean;
};

export type EnhancedGraphCanvasHandle = {
  exportPNG: () => string | null;
  exportSVG: () => string | null;
  resetView: () => void;
  focusNode: (nodeId: string) => void;
  getVisibleNodes: () => Node[];
  applyFilter: (filter: (node: Node) => boolean) => void;
};

type FilterOptions = {
  minEnergy: number;
  maxEnergy: number;
  selectedTags: string[];
  selectedStates: string[];
  timeRange: [number, number]; // days ago
};

const EnhancedGraphCanvas = forwardRef<EnhancedGraphCanvasHandle, Props>(
  function EnhancedGraphCanvas({ 
    data, 
    width = 800, 
    height = 600, 
    onNodeClick, 
    onEdgeClick,
    showHeatmap = true, 
    showClusters = true,
    showTrends = false,
    enableFiltering = true
  }, ref) {
    
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const [dpr, setDpr] = useState<number>(1);
    const [pan, setPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
    const [scale, setScale] = useState<number>(1);
    const [layout, setLayout] = useState<{ nodes: Record<string, Node> }>({ nodes: {} });
    const [filteredData, setFilteredData] = useState<GraphData | null>(null);
    const [selectedNode, setSelectedNode] = useState<string | null>(null);
    const [hoveredNode, setHoveredNode] = useState<string | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState<{ x: number; y: number } | null>(null);
    
    // Фильтры
    const [filters, setFilters] = useState<FilterOptions>({
      minEnergy: 0,
      maxEnergy: 1,
      selectedTags: [],
      selectedStates: [],
      timeRange: [0, 30] // последние 30 дней
    });
    
    // Настройки визуализации
    const [visualSettings, setVisualSettings] = useState({
      nodeSize: 1.0,
      edgeWidth: 1.0,
      showLabels: true,
      showEnergy: true,
      animateChanges: true,
      colorScheme: 'energy' as 'energy' | 'emotion' | 'age' | 'tags'
    });

    // Initialize DPR
    useEffect(() => { 
      setDpr(typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1); 
    }, []);

    // Apply filters to data
    useEffect(() => {
      if (!data) {
        setFilteredData(null);
        return;
      }

      const now = new Date();
      const minDate = new Date(now.getTime() - filters.timeRange[1] * 24 * 60 * 60 * 1000);
      const maxDate = new Date(now.getTime() - filters.timeRange[0] * 24 * 60 * 60 * 1000);

      const filteredNodes = data.nodes.filter(node => {
        // Energy filter
        const energy = node.energy_weight || 0;
        if (energy < filters.minEnergy || energy > filters.maxEnergy) return false;

        // Tags filter
        if (filters.selectedTags.length > 0) {
          const nodeTags = node.tags || [];
          if (!filters.selectedTags.some(tag => nodeTags.includes(tag))) return false;
        }

        // State filter
        if (filters.selectedStates.length > 0) {
          if (!filters.selectedStates.includes(node.state || 'unknown')) return false;
        }

        // Time filter
        if (node.created_at) {
          const nodeDate = new Date(node.created_at);
          if (nodeDate < minDate || nodeDate > maxDate) return false;
        }

        return true;
      });

      const filteredNodeIds = new Set(filteredNodes.map(n => n.id));
      const filteredEdges = data.edges.filter(edge => 
        filteredNodeIds.has(edge.source) && filteredNodeIds.has(edge.target)
      );

      setFilteredData({
        nodes: filteredNodes,
        edges: filteredEdges
      });
    }, [data, filters]);

    // Enhanced force-directed layout with better physics
    useEffect(() => {
      const gd = filteredData || { nodes: [], edges: [] };
      if (gd.nodes.length === 0) {
        setLayout({ nodes: {} });
        return;
      }

      const nodes: Record<string, Node> = {};
      
      // Initialize positions in a circle or grid
      gd.nodes.forEach((n, i) => {
        const angle = (i / gd.nodes.length) * Math.PI * 2;
        const radius = Math.sqrt(gd.nodes.length) * 30;
        nodes[n.id] = { 
          ...n, 
          x: Math.cos(angle) * radius, 
          y: Math.sin(angle) * radius 
        };
      });

      // Enhanced physics simulation
      const repulsion = 3000;
      const attraction = 0.02;
      const damping = 0.9;
      const centeringForce = 0.001;

      for (let iter = 0; iter < 150; iter++) {
        const keys = Object.keys(nodes);
        
        // Apply repulsion between all nodes
        for (let i = 0; i < keys.length; i++) {
          for (let j = i + 1; j < keys.length; j++) {
            const a = nodes[keys[i]];
            const b = nodes[keys[j]];
            if (!a || !b) continue;
            
            const dx = a.x! - b.x!;
            const dy = a.y! - b.y!;
            const dist2 = Math.max(1, dx * dx + dy * dy);
            const dist = Math.sqrt(dist2);
            
            // Energy-based repulsion (higher energy nodes repel more)
            const energyFactor = ((a.energy_weight || 0.5) + (b.energy_weight || 0.5)) / 2;
            const force = (repulsion * energyFactor) / dist2;
            
            const fx = (dx / dist) * force;
            const fy = (dy / dist) * force;
            
            a.x! += fx * damping;
            a.y! += fy * damping;
            b.x! -= fx * damping;
            b.y! -= fy * damping;
          }
        }

        // Apply attraction for connected nodes
        gd.edges.forEach(edge => {
          const a = nodes[edge.source];
          const b = nodes[edge.target];
          if (!a || !b) return;
          
          const dx = b.x! - a.x!;
          const dy = b.y! - a.y!;
          const dist = Math.sqrt(dx * dx + dy * dy);
          
          if (dist > 0) {
            // Strength-based attraction
            const strength = edge.strength || 0.5;
            const force = attraction * strength * dist;
            
            const fx = (dx / dist) * force;
            const fy = (dy / dist) * force;
            
            a.x! += fx;
            a.y! += fy;
            b.x! -= fx;
            b.y! -= fy;
          }
        });

        // Apply centering force
        keys.forEach(key => {
          const node = nodes[key];
          node.x! *= (1 - centeringForce);
          node.y! *= (1 - centeringForce);
        });
      }

      setLayout({ nodes });
    }, [filteredData]);

    // Enhanced drawing with better visuals
    const draw = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const W = width * dpr;
      const H = height * dpr;
      canvas.width = W;
      canvas.height = H;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      ctx.clearRect(0, 0, W, H);
      ctx.save();
      ctx.translate(W / 2 + pan.x * dpr, H / 2 + pan.y * dpr);
      ctx.scale(scale, scale);

      const nodes = layout.nodes;
      const edges = filteredData?.edges || [];

      // Draw heatmap layer
      if (showHeatmap) {
        Object.values(nodes).forEach(node => {
          const energy = node.energy_weight || 0;
          if (energy <= 0) return;

          const radius = 60 + energy * 100;
          const gradient = ctx.createRadialGradient(node.x!, node.y!, 0, node.x!, node.y!, radius);

          // hsla color with alpha instead of concatenating invalid suffixes
          const hue = Math.max(0, Math.min(360, energy * 60));
          gradient.addColorStop(0, `hsla(${hue}, 100%, 50%, 0.12)`);
          gradient.addColorStop(1, `hsla(${hue}, 100%, 50%, 0)`);

          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, radius, 0, Math.PI * 2);
          ctx.fill();
        });
      }

      // Draw trend lines if enabled
      if (showTrends) {
        drawTrendLines(ctx, nodes);
      }

      // Draw edges with enhanced styling
      edges.forEach(edge => {
        const source = nodes[edge.source];
        const target = nodes[edge.target];
        if (!source || !target) return;

        const strength = edge.strength || 0.5;
        const alpha = Math.max(0.1, strength);
        
        ctx.strokeStyle = `rgba(100, 150, 200, ${alpha})`;
        ctx.lineWidth = (strength * 3 + 1) * visualSettings.edgeWidth * (dpr / scale);
        
        // Connection type styling
        if (edge.connection_type === 'semantic') {
          ctx.setLineDash([5, 5]);
        } else if (edge.connection_type === 'temporal') {
          ctx.setLineDash([10, 2]);
        } else {
          ctx.setLineDash([]);
        }
        
        ctx.beginPath();
        ctx.moveTo(source.x!, source.y!);
        ctx.lineTo(target.x!, target.y!);
        ctx.stroke();
        
        // Draw strength indicator
        if (strength > 0.7) {
          const midX = (source.x! + target.x!) / 2;
          const midY = (source.y! + target.y!) / 2;
          
          ctx.fillStyle = 'rgba(255, 200, 0, 0.8)';
          ctx.beginPath();
          ctx.arc(midX, midY, 3, 0, Math.PI * 2);
          ctx.fill();
        }
      });

      // Draw clusters if enabled
      if (showClusters) {
        drawClusters(ctx, nodes);
      }

      // Draw nodes with enhanced styling
      Object.values(nodes).forEach(node => {
        const energy = node.energy_weight || 0.5;
        const baseRadius = 8 + energy * 12;
        const radius = baseRadius * visualSettings.nodeSize;
        
        // Node color based on color scheme
        const nodeColor = getNodeColor(node, visualSettings.colorScheme);
        
        // Highlight selected/hovered nodes
        if (selectedNode === node.id) {
          ctx.strokeStyle = '#ff4d4f';
          ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, radius + 4, 0, Math.PI * 2);
          ctx.stroke();
        } else if (hoveredNode === node.id) {
          ctx.strokeStyle = '#1890ff';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, radius + 2, 0, Math.PI * 2);
          ctx.stroke();
        }
        
        // Main node circle
        ctx.fillStyle = nodeColor;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(node.x!, node.y!, radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        
        // Energy indicator ring
        if (visualSettings.showEnergy && energy > 0) {
          const ringRadius = radius + 3;
          const ringWidth = 2;
          
          ctx.strokeStyle = `rgba(0, 255, 0, ${energy})`;
          ctx.lineWidth = ringWidth;
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, ringRadius, 0, Math.PI * 2 * energy);
          ctx.stroke();
        }
        
        // Delta energy indicator
        if (node.delta_energy && Math.abs(node.delta_energy) > 0.01) {
          const deltaColor = node.delta_energy > 0 ? '#52c41a' : '#f5222d';
          const deltaSize = Math.abs(node.delta_energy) * 10;
          
          ctx.fillStyle = deltaColor;
          ctx.beginPath();
          ctx.arc(node.x! + radius, node.y! - radius, deltaSize, 0, Math.PI * 2);
          ctx.fill();
        }
        
        // Node labels
        if (visualSettings.showLabels && scale > 0.5) {
          ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
          ctx.font = `${12 / scale}px Arial`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          
          const label = node.thought_form?.substring(0, 20) || node.id.substring(0, 8);
          ctx.fillText(label, node.x!, node.y! + radius + 15);
        }
      });

      ctx.restore();
    }, [layout, filteredData, pan, scale, dpr, width, height, selectedNode, hoveredNode, showHeatmap, showClusters, showTrends, visualSettings]);

    useEffect(() => {
      draw();
    }, [draw]);

    // Helper functions
    const getNodeColor = (node: Node, colorScheme: string): string => {
      switch (colorScheme) {
        case 'energy':
          const energy = node.energy_weight || 0.5;
          return `hsl(${energy * 120}, 70%, 60%)`; // Green to red
        
        case 'emotion':
          const emotion = node.composite_emotion;
          if (emotion?.valence !== undefined) {
            const hue = emotion.valence > 0 ? 120 : 0; // Green for positive, red for negative
            const saturation = Math.abs(emotion.valence) * 70 + 30;
            return `hsl(${hue}, ${saturation}%, 60%)`;
          }
          return '#8c8c8c';
        
        case 'age':
          if (node.created_at) {
            const age = (Date.now() - new Date(node.created_at).getTime()) / (1000 * 60 * 60 * 24);
            const hue = Math.max(0, 240 - age * 10); // Blue to red over time
            return `hsl(${hue}, 70%, 60%)`;
          }
          return '#8c8c8c';
        
        case 'tags':
          const tags = node.tags || [];
          if (tags.length > 0) {
            const hash = tags.join('').split('').reduce((a, b) => {
              a = ((a << 5) - a) + b.charCodeAt(0);
              return a & a;
            }, 0);
            const hue = Math.abs(hash) % 360;
            return `hsl(${hue}, 70%, 60%)`;
          }
          return '#8c8c8c';
        
        default:
          return '#1890ff';
      }
    };

    const getHeatmapColor = (energy: number): string => {
      const hue = Math.max(0, Math.min(360, energy * 60)); // 0 (red) to 60 (yellow)
      return `hsl(${hue}, 100%, 50%)`;
    };

    const drawTrendLines = (ctx: CanvasRenderingContext2D, nodes: Record<string, Node>) => {
      // Group nodes by time and draw trend lines
      const nodesByTime = Object.values(nodes)
        .filter(n => n.created_at)
        .sort((a, b) => new Date(a.created_at!).getTime() - new Date(b.created_at!).getTime());
      
      if (nodesByTime.length < 2) return;
      
      ctx.strokeStyle = 'rgba(255, 165, 0, 0.3)';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      
      ctx.beginPath();
      nodesByTime.forEach((node, i) => {
        if (i === 0) {
          ctx.moveTo(node.x!, node.y!);
        } else {
          ctx.lineTo(node.x!, node.y!);
        }
      });
      ctx.stroke();
      ctx.setLineDash([]);
    };

    const drawClusters = (ctx: CanvasRenderingContext2D, nodes: Record<string, Node>) => {
      // Simple clustering based on proximity
      const nodeList = Object.values(nodes);
      const clusters: Node[][] = [];
      const visited = new Set<string>();
      
      nodeList.forEach(node => {
        if (visited.has(node.id)) return;
        
        const cluster = [node];
        visited.add(node.id);
        
        // Find nearby nodes
        nodeList.forEach(other => {
          if (visited.has(other.id)) return;
          
          const dx = node.x! - other.x!;
          const dy = node.y! - other.y!;
          const dist = Math.sqrt(dx * dx + dy * dy);
          
          if (dist < 100) { // Cluster threshold
            cluster.push(other);
            visited.add(other.id);
          }
        });
        
        if (cluster.length > 1) {
          clusters.push(cluster);
        }
      });
      
      // Draw cluster boundaries
      clusters.forEach((cluster, i) => {
        const hue = (i * 137.5) % 360; // Golden angle for color distribution
        ctx.strokeStyle = `hsla(${hue}, 50%, 50%, 0.3)`;
        ctx.fillStyle = `hsla(${hue}, 50%, 50%, 0.1)`;
        ctx.lineWidth = 2;
        
        // Calculate cluster bounds
        const xs = cluster.map(n => n.x!);
        const ys = cluster.map(n => n.y!);
        const minX = Math.min(...xs) - 20;
        const maxX = Math.max(...xs) + 20;
        const minY = Math.min(...ys) - 20;
        const maxY = Math.max(...ys) + 20;
        
        // Draw cluster rectangle
        ctx.beginPath();
        ctx.roundRect(minX, minY, maxX - minX, maxY - minY, 10);
        ctx.fill();
        ctx.stroke();
      });
    };

    // Mouse event handlers
    const handleMouseDown = (e: React.MouseEvent) => {
      setIsDragging(true);
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    };

    const handleMouseMove = (e: React.MouseEvent) => {
      if (isDragging && dragStart) {
        setPan({
          x: e.clientX - dragStart.x,
          y: e.clientY - dragStart.y
        });
      } else {
        // Check for node hover
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        
        const x = (e.clientX - rect.left - width/2 - pan.x) / scale;
        const y = (e.clientY - rect.top - height/2 - pan.y) / scale;
        
        let hoveredNodeId = null;
        for (const node of Object.values(layout.nodes)) {
          const dx = x - node.x!;
          const dy = y - node.y!;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const radius = 8 + (node.energy_weight || 0.5) * 12;
          
          if (dist <= radius) {
            hoveredNodeId = node.id;
            break;
          }
        }
        
        setHoveredNode(hoveredNodeId);
      }
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      setDragStart(null);
    };

    const handleClick = (e: React.MouseEvent) => {
      if (isDragging) return;
      
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;
      
      const x = (e.clientX - rect.left - width/2 - pan.x) / scale;
      const y = (e.clientY - rect.top - height/2 - pan.y) / scale;
      
      for (const node of Object.values(layout.nodes)) {
        const dx = x - node.x!;
        const dy = y - node.y!;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const radius = 8 + (node.energy_weight || 0.5) * 12;
        
        if (dist <= radius) {
          setSelectedNode(node.id);
          onNodeClick?.(node);
          return;
        }
      }
      
      setSelectedNode(null);
    };

    const handleWheel = (e: React.WheelEvent) => {
      // Не вызываем preventDefault внутри возможного пассивного слушателя
      const delta = e.deltaY > 0 ? 0.9 : 1.1;
      setScale(prev => Math.max(0.1, Math.min(3, prev * delta)));
    };

    // Imperative handle
    useImperativeHandle(ref, () => ({
      exportPNG: () => {
        const canvas = canvasRef.current;
        return canvas ? canvas.toDataURL('image/png') : null;
      },
      
      exportSVG: () => {
        // SVG export would require a separate implementation
        return null;
      },
      
      resetView: () => {
        setPan({ x: 0, y: 0 });
        setScale(1);
        setSelectedNode(null);
      },
      
      focusNode: (nodeId: string) => {
        const node = layout.nodes[nodeId];
        if (node) {
          setPan({ x: -node.x! * scale, y: -node.y! * scale });
          setSelectedNode(nodeId);
        }
      },
      
      getVisibleNodes: () => {
        return Object.values(layout.nodes);
      },
      
      applyFilter: (filter: (node: Node) => boolean) => {
        if (!data) return;
        
        const filteredNodes = data.nodes.filter(filter);
        const filteredNodeIds = new Set(filteredNodes.map(n => n.id));
        const filteredEdges = data.edges.filter(edge => 
          filteredNodeIds.has(edge.source) && filteredNodeIds.has(edge.target)
        );
        
        setFilteredData({ nodes: filteredNodes, edges: filteredEdges });
      }
    }));

    // Get available tags and states for filters
    const availableTags = Array.from(new Set(
      (data?.nodes || []).flatMap(node => node.tags || [])
    ));
    
    const availableStates = Array.from(new Set(
      (data?.nodes || []).map(node => node.state || 'unknown')
    ));

    return (
      <div style={{ position: 'relative' }}>
        {/* Controls */}
        <Card 
          size="small" 
          style={{ 
            position: 'absolute', 
            top: 10, 
            left: 10, 
            zIndex: 10,
            minWidth: 200
          }}
        >
          <Space direction="vertical" size="small">
            <Space wrap>
              <Tooltip title="Увеличить">
                <Button 
                  size="small" 
                  icon={<ZoomInIcon size={14} />}
                  onClick={() => setScale(prev => Math.min(3, prev * 1.2))}
                />
              </Tooltip>
              <Tooltip title="Уменьшить">
                <Button 
                  size="small" 
                  icon={<ZoomOutIcon size={14} />}
                  onClick={() => setScale(prev => Math.max(0.1, prev / 1.2))}
                />
              </Tooltip>
              <Tooltip title="Сбросить вид">
                <Button 
                  size="small" 
                  icon={<RotateCcwIcon size={14} />}
                  onClick={() => {
                    setPan({ x: 0, y: 0 });
                    setScale(1);
                  }}
                />
              </Tooltip>
              <Tooltip title="Экспорт PNG">
                <Button 
                  size="small" 
                  icon={<DownloadIcon size={14} />}
                  onClick={() => {
                    const canvas = canvasRef.current;
                    if (canvas) {
                      const link = document.createElement('a');
                      link.download = 'soul-graph.png';
                      link.href = canvas.toDataURL();
                      link.click();
                    }
                  }}
                />
              </Tooltip>
            </Space>
            
            <Space>
              <span>Размер узлов:</span>
              <Slider
                min={0.5}
                max={2}
                step={0.1}
                value={visualSettings.nodeSize}
                onChange={(value) => setVisualSettings(prev => ({ ...prev, nodeSize: value }))}
                style={{ width: 80 }}
              />
            </Space>
            
            <Space>
              <span>Цветовая схема:</span>
              <Select
                size="small"
                value={visualSettings.colorScheme}
                onChange={(value) => setVisualSettings(prev => ({ ...prev, colorScheme: value }))}
                style={{ width: 100 }}
              >
                <Select.Option value="energy">Энергия</Select.Option>
                <Select.Option value="emotion">Эмоции</Select.Option>
                <Select.Option value="age">Возраст</Select.Option>
                <Select.Option value="tags">Теги</Select.Option>
              </Select>
            </Space>
            
            <Space wrap>
              <Switch
                size="small"
                checked={showHeatmap}
                onChange={(checked) => setVisualSettings(prev => ({ ...prev, showHeatmap: checked }))}
              />
              <span>Тепловая карта</span>
              
              <Switch
                size="small"
                checked={visualSettings.showLabels}
                onChange={(checked) => setVisualSettings(prev => ({ ...prev, showLabels: checked }))}
              />
              <span>Метки</span>
            </Space>
          </Space>
        </Card>

        {/* Filters */}
        {enableFiltering && (
          <Card 
            size="small" 
            style={{ 
              position: 'absolute', 
              top: 10, 
              right: 10, 
              zIndex: 10,
              minWidth: 250
            }}
          >
            <Space direction="vertical" size="small">
              <div>
                <span>Энергия:</span>
                <Slider
                  range
                  min={0}
                  max={1}
                  step={0.01}
                  value={[filters.minEnergy, filters.maxEnergy]}
                  onChange={([min, max]) => setFilters(prev => ({ ...prev, minEnergy: min, maxEnergy: max }))}
                />
              </div>
              
              {availableTags.length > 0 && (
                <div>
                  <span>Теги:</span>
                  <Select
                    mode="multiple"
                    size="small"
                    placeholder="Выберите теги"
                    value={filters.selectedTags}
                    onChange={(tags) => setFilters(prev => ({ ...prev, selectedTags: tags }))}
                    style={{ width: '100%' }}
                  >
                    {availableTags.map(tag => (
                      <Select.Option key={tag} value={tag}>{tag}</Select.Option>
                    ))}
                  </Select>
                </div>
              )}
              
              <div>
                <span>Период (дни назад):</span>
                <Slider
                  range
                  min={0}
                  max={90}
                  value={filters.timeRange}
                  onChange={(range) => setFilters(prev => ({ ...prev, timeRange: range as [number, number] }))}
                />
              </div>
            </Space>
          </Card>
        )}

        {/* Main canvas */}
        <canvas
          ref={canvasRef}
          style={{ 
            border: '1px solid #d9d9d9',
            cursor: isDragging ? 'grabbing' : 'grab',
            // Предотвращаем нежелательный скролл/зум страницы на тач/колесо
            touchAction: 'none',
            overscrollBehavior: 'none'
          }}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          onWheel={handleWheel}
        />

        {/* Info panel */}
        {selectedNode && layout.nodes[selectedNode] && (
          <Card 
            size="small" 
            title="Информация о узле"
            style={{ 
              position: 'absolute', 
              bottom: 10, 
              left: 10, 
              zIndex: 10,
              maxWidth: 300
            }}
          >
            {(() => {
              const node = layout.nodes[selectedNode];
              return (
                <Space direction="vertical" size="small">
                  <div><strong>ID:</strong> {node.id}</div>
                  <div><strong>Энергия:</strong> {(node.energy_weight || 0).toFixed(3)}</div>
                  {node.tags && node.tags.length > 0 && (
                    <div><strong>Теги:</strong> {node.tags.join(', ')}</div>
                  )}
                  {node.thought_form && (
                    <div><strong>Мысль:</strong> {node.thought_form.substring(0, 100)}...</div>
                  )}
                  {node.composite_emotion && (
                    <div>
                      <strong>Эмоция:</strong> {node.composite_emotion.label} 
                      (валентность: {(node.composite_emotion.valence || 0).toFixed(2)})
                    </div>
                  )}
                </Space>
              );
            })()}
          </Card>
        )}
      </div>
    );
  }
);

export default EnhancedGraphCanvas;
